catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }
   var currentYear = new Date().getFullYear();
   var isValidFormat = /^\d{4}$/.test(newValue);
   if (!isValidFormat) {
        g_form.addErrorMessage('Please enter a valid 4-digit year (e.g., 2024).');
        g_form.setValue('release_year', '');
    } else if (parseInt(newValue) > currentYear) { 
        g_form.addErrorMessage('Release year cannot be that far in the future.');
        g_form.setValue('release_year', '');
    } else if (parseInt(newValue) < 1895){
		g_form.addErrorMessage('Release year cannot be that far in the past.');
        g_form.setValue('release_year', '');
	} else {
		g_form.clearMessages();
    }
}
